	["Features/ServerHop.lua"] = [======[
-- ServerHop owns moving between servers and watching who is in this one,
-- ported from Iambatman:
--   Rejoin, Server Hop (a random public server with a free slot) and joining
--   a server by Job ID; reading the public server list for the browser;
--   Leave On Danger Group: when a member of any group in DANGER_GROUP_IDS
--   who is not on the Danger Whitelist (nor, with Whitelist Skips Safety on,
--   the Auto Block whitelist) is in the server, it blocks them and then
--   joins another public server (toggle, groups and whitelist are global,
--   not per profile); Join Alerts for players off the Auto Block whitelist;
--   and the Player Log of who joined and left.
-- ServerUI draws all of it on the Server tab.
return {
    Name = "ServerHop",
    IsFeature = true,
    Dependencies = {"Runtime", "SaveConfig", "AutoBlock"},

    Start = function(Context)
        local Services = Context.Services
        local Players = Services.Players
        local HttpService = Services.HttpService
        local TeleportService = game:GetService("TeleportService")
        local Player = Context.Player
        local Feature = Context.Feature
        local CONFIG = Context.CONFIG
        local AICFeature = Context.AICFeature
        local NotifyAction = Context.NotifyAction

        local DANGER_HOP_MAX_ATTEMPTS = 3
        local DANGER_HOP_RETRY_DELAY = 3
        --// How long a danger hop waits for the block to take before leaving
        --// anyway (time to press Block by hand when Auto Confirm Block is
        --// off), and how often it looks.
        local DANGER_BLOCK_WAIT = 10
        local DANGER_BLOCK_POLL = 0.25
        local GROUP_CHECK_MAX_ATTEMPTS = 3
        local GROUP_CHECK_RETRY_DELAY = 5
        --// Players are checked again this often, so a player taken off the
        --// whitelist, or a toggle switched on, is acted on.
        local SCAN_INTERVAL = 2
        --// Pages of the public server list a hop reads before giving up.
        local HOP_MAX_PAGES = 4
        local LOG_LIMIT = 100
        --// The same notice is not shown again within this.
        local NOTICE_COOLDOWN = 8
        --// One "could not check" notice at most this often, however many
        --// players' group checks fail (the details go to the console).
        local GROUP_CHECK_NOTICE_COOLDOWN = 60
        --// Join alerts arriving within this are shown as one notice.
        local JOIN_ALERT_BATCH_SECONDS = 1.5
        --// Names listed in one notice; the rest are counted.
        local JOIN_ALERT_MAX_NAMES = 4
        --// A player who leaves and comes back within this is not announced
        --// again.
        local JOIN_ALERT_REPEAT_SECONDS = 120
        local SERVER_LIST_URL = "https://games.roblox.com/v1/games/%d/servers/Public?sortOrder=Asc&limit=100"

        local ServerHop = {
            Name = "ServerHop",
            IsFeature = true,
            S = {
                Teleporting = false,
                --// A hop is reading the server list.
                Finding = false,
                Status = "IDLE",
                --// Notice key -> os.clock() it was last shown.
                NoticeAt = {},
                --// Join alerts waiting to be shown together.
                AlertQueue = {},
                AlertFlushScheduled = false,
                --// UserId -> the danger group ID they were found in.
                DangerUsers = {},
                --// Bumped when the group list changes, so a check that was
                --// asking about the old list is dropped.
                GroupListVersion = 0,
                CheckedUsers = {},
                CheckInFlight = {},
                CheckFailures = {},
                DangerHopStarted = false,
                DangerHopAttempts = 0,
                --// UserId -> os.clock() of their last join alert.
                AlertSeen = {},
                Log = {},
                --// Bumped on every log change, so the UI redraws only then.
                LogVersion = 0,
                Online = {},
                LastScan = 0,
                --// Set by the first Update, once the profile is loaded.
                Ready = false,
            },
        }

        local S = ServerHop.S

        --// The Auto Block whitelist, which Join Alerts goes by.
        local function IsWhitelisted(OtherPlayer)
            return AICFeature.IsWhitelisted ~= nil and AICFeature.IsWhitelisted(OtherPlayer.UserId) == true
        end

        --// Leave On Danger Group's own whitelist (CONFIG.DANGER_WHITELIST),
        --// global and separate from the Auto Block one.
        function ServerHop:IsDangerWhitelisted(UserId)
            local Id = tostring(UserId or ""):gsub("%s+", "")
            return table.find(CONFIG.DANGER_WHITELIST or {}, Id) ~= nil
        end

        local function SetStatus(Text)
            S.Status = Text
        end

        --// Every notice goes through here, so a repeat within Cooldown
        --// (NOTICE_COOLDOWN by default) is dropped. Key defaults to the
        --// title and message.
        local function Notify(Title, Message, Duration, Key, Cooldown)
            Key = Key or (Title .. "|" .. Message)

            local now = os.clock()

            if now - (S.NoticeAt[Key] or -math.huge) < (Cooldown or NOTICE_COOLDOWN) then
                return
            end

            S.NoticeAt[Key] = now
            NotifyAction(Title, Message, Duration)
        end

        function ServerHop:GetStatus()
            return S.Status
        end

        function ServerHop:IsDangerPlayer(OtherPlayer)
            return S.DangerUsers[tostring(OtherPlayer.UserId)] ~= nil
        end

        --// CONFIG.DANGER_GROUP_IDS as numbers.
        local function GetDangerGroupIds()
            local Ids = {}

            for _, Text in ipairs(CONFIG.DANGER_GROUP_IDS or {}) do
                local Id = tonumber(Text)

                if Id then
                    table.insert(Ids, Id)
                end
            end

            return Ids
        end

        --// The group list changed: everyone is asked again about the new one.
        function ServerHop:ResetGroupChecks()
            S.GroupListVersion += 1
            table.clear(S.DangerUsers)
            table.clear(S.CheckedUsers)
            table.clear(S.CheckInFlight)
            table.clear(S.CheckFailures)
            S.LastScan = 0
            S.LogVersion += 1
        end

        ------------------------------------------------------------------------
        --// Player Log
        ------------------------------------------------------------------------

        local function RecordLog(OtherPlayer, Event)
            if not OtherPlayer or OtherPlayer == Player then
                return
            end

            table.insert(S.Log, {
                Time = os.date("%H:%M:%S"),
                Event = Event,
                Name = OtherPlayer.Name,
                UserId = tostring(OtherPlayer.UserId),
            })

            while #S.Log > LOG_LIMIT do
                table.remove(S.Log, 1)
            end

            S.LogVersion += 1
        end

        --// Newest first.
        function ServerHop:GetLog()
            local Result = {}

            for Index = #S.Log, 1, -1 do
                table.insert(Result, S.Log[Index])
            end

            return Result
        end

        function ServerHop:ClearLog()
            table.clear(S.Log)
            S.LogVersion += 1
        end

        ------------------------------------------------------------------------
        --// Teleports
        ------------------------------------------------------------------------

        local function TeleportToInstance(JobId, Status, OnFailed)
            if S.Teleporting then
                return false
            end

            S.Teleporting = true
            SetStatus(Status)

            task.spawn(function()
                --// The Webhook report goes while the client is still here.
                if AICFeature.ReportBeforeLeave then
                    AICFeature.ReportBeforeLeave()
                end

                local Success, Error = pcall(function()
                    TeleportService:TeleportToPlaceInstance(game.PlaceId, JobId, Player)
                end)

                if not Success then
                    S.Teleporting = false
                    SetStatus("TELEPORT FAILED")
                    Notify("SERVER", tostring(Error), 6)

                    if OnFailed then
                        OnFailed(tostring(Error))
                    end
                end
            end)

            return true
        end

        function ServerHop:Rejoin()
            local JobId = tostring(game.JobId or "")

            if JobId == "" then
                Notify("SERVER", "This server has no Job ID, so Rejoin is unavailable", 4)
                return false
            end

            Notify("SERVER", "Rejoining this server...")
            return TeleportToInstance(JobId, "REJOINING")
        end

        function ServerHop:Join(JobId)
            JobId = tostring(JobId or ""):gsub("%s+", "")

            if JobId == "" or JobId == game.JobId then
                Notify("SERVER", "That Job ID is empty or is this server", 4)
                return false
            end

            return TeleportToInstance(JobId, "JOINING SERVER")
        end

        --// One page of public servers with a free slot, other than this one.
        --// Returns the servers and the next page's cursor, or nil and an error.
        function ServerHop:ReadPublicServers(Cursor)
            local Url = string.format(SERVER_LIST_URL, game.PlaceId)

            if type(Cursor) == "string" and Cursor ~= "" then
                Url ..= "&cursor=" .. HttpService:UrlEncode(Cursor)
            end

            local Success, Body = pcall(function()
                return game:HttpGet(Url)
            end)

            if not Success then
                return nil, nil, Body
            end

            local Decoded, Payload = pcall(function()
                return HttpService:JSONDecode(Body)
            end)

            if not Decoded or type(Payload) ~= "table" or type(Payload.data) ~= "table" then
                return nil, nil, "The public server list response was invalid"
            end

            local Servers = {}

            for _, Server in ipairs(Payload.data) do
                local Playing = tonumber(Server.playing)
                local MaxPlayers = tonumber(Server.maxPlayers)

                if type(Server.id) == "string" and Server.id ~= game.JobId
                    and Playing and MaxPlayers and Playing < MaxPlayers
                then
                    table.insert(Servers, {
                        Id = Server.id,
                        Playing = Playing,
                        MaxPlayers = MaxPlayers,
                        Ping = tonumber(Server.ping),
                        FPS = tonumber(Server.fps),
                    })
                end
            end

            local NextCursor = type(Payload.nextPageCursor) == "string" and Payload.nextPageCursor or nil
            return Servers, NextCursor
        end

        --// The Job ID of a random public server with a free slot other than
        --// this one, or nil and why (nil error: there is none). Yields.
        local function FindOtherServer()
            local Cursor

            for _ = 1, HOP_MAX_PAGES do
                local Servers, NextCursor, ReadError = ServerHop:ReadPublicServers(Cursor)

                if not Servers then
                    return nil, ReadError
                end

                if #Servers > 0 then
                    return Servers[math.random(1, #Servers)].Id
                end

                Cursor = NextCursor

                if not Cursor then
                    break
                end
            end

            return nil, nil
        end

        --// Finds another public server and joins it. OnFailed is called when
        --// a hop was started but could not be carried out -- the server list
        --// could not be read, no other server had a free slot, or the
        --// teleport was refused -- so a caller that has to get out of this
        --// server can fall back to stopping the farm.
        --// Returns false when another hop is already on its way: that is
        --// still leaving, for somebody else's reason.
        function ServerHop:Hop(OnFailed)
            --// A second press while one is finding or teleporting does nothing.
            if S.Teleporting or S.Finding then
                return false
            end

            S.Finding = true
            SetStatus("FINDING SERVER")

            task.spawn(function()
                local Target, Error = FindOtherServer()

                S.Finding = false

                if Target then
                    Notify("SERVER HOP", "Joining another public server...")
                    TeleportToInstance(Target, "HOPPING", OnFailed)
                elseif Error then
                    SetStatus("HOP FAILED")
                    Notify("SERVER HOP", "Could not read the server list: " .. tostring(Error), 6)

                    if OnFailed then
                        OnFailed(tostring(Error))
                    end
                else
                    SetStatus("NO OTHER SERVER")
                    Notify("SERVER HOP", "No other public server with a free slot was found", 6)

                    if OnFailed then
                        OnFailed("no other server with a free slot")
                    end
                end
            end)

            return true
        end

        ------------------------------------------------------------------------
        --// Leave On Danger Group
        ------------------------------------------------------------------------

        --// Whitelist Skips Safety also exempts the Auto Block whitelist.
        local function IsSafetyExempt(OtherPlayer)
            return AICFeature.IsSafetyExempt ~= nil and AICFeature.IsSafetyExempt(OtherPlayer.UserId) == true
        end

        local function ShouldLeaveFor(OtherPlayer)
            return Feature.DangerGroupHop.Enabled
                and OtherPlayer.Parent == Players
                and ServerHop:IsDangerPlayer(OtherPlayer)
                and not ServerHop:IsDangerWhitelisted(OtherPlayer.UserId)
                and not IsSafetyExempt(OtherPlayer)
        end

        local function IsBlocked(OtherPlayer)
            return AICFeature.isBlocked ~= nil and AICFeature.isBlocked(OtherPlayer.UserId) == true
        end

        --// Auto Block's check that the block has gone through, not just
        --// shown up on the list.
        local function IsBlockSettled(OtherPlayer)
            if AICFeature.IsBlockSettled then
                return AICFeature.IsBlockSettled(OtherPlayer) == true
            end

            return IsBlocked(OtherPlayer)
        end

        --// Blocks the player through Auto Block's prompt (Auto Confirm Block
        --// presses it when on) and waits, at most DANGER_BLOCK_WAIT, for the
        --// block to go through. Roblox does not put us in a server with
        --// someone we blocked, so without this a hop can land straight back
        --// here. True when they are blocked. Yields.
        local function BlockBeforeLeaving(OtherPlayer)
            if not IsBlocked(OtherPlayer) then
                if not AICFeature.promptBlockPlayer then
                    return false
                end

                SetStatus("BLOCKING @" .. OtherPlayer.Name .. " (DANGER GROUP)")
                AICFeature.promptBlockPlayer(OtherPlayer)
            end

            local Deadline = os.clock() + DANGER_BLOCK_WAIT

            while os.clock() < Deadline and OtherPlayer.Parent == Players do
                if IsBlockSettled(OtherPlayer) then
                    return true
                end

                --// Taken off the list again (the block failed): ask again.
                if not IsBlocked(OtherPlayer) and AICFeature.promptBlockPlayer then
                    AICFeature.promptBlockPlayer(OtherPlayer)
                end

                task.wait(DANGER_BLOCK_POLL)
            end

            return IsBlockSettled(OtherPlayer)
        end

        --// Blocks the danger player first, then joins another public server
        --// from the list, so it cannot be this one. Without a readable list
        --// it lets Roblox pick a server instead.
        local function LeaveFor(OtherPlayer)
            if S.DangerHopStarted
                or S.DangerHopAttempts >= DANGER_HOP_MAX_ATTEMPTS
                or not ShouldLeaveFor(OtherPlayer)
            then
                return
            end

            S.DangerHopStarted = true
            S.DangerHopAttempts += 1
            S.Teleporting = true

            if S.DangerHopAttempts == 1 then
                local GroupId = S.DangerUsers[tostring(OtherPlayer.UserId)]
                Notify("DANGER", string.format("@%s is in group %s. Blocking, then leaving this server.", OtherPlayer.Name, tostring(GroupId)), 7)
            end

            task.spawn(function()
                --// Nothing leaves the instant a Danger Group member is
                --// spotted: the same random 2-4 s pause every other leave
                --// takes runs first (Random Leave Delay), and what was
                --// decided before it is looked at again after it.
                local Wait = AICFeature.LeaveDelay and AICFeature.LeaveDelay() or 0

                if Wait > 0 then
                    task.wait(Wait)

                    if OtherPlayer.Parent ~= Players or not ShouldLeaveFor(OtherPlayer) then
                        S.DangerHopAttempts = math.max(S.DangerHopAttempts - 1, 0)
                        S.DangerHopStarted = false
                        S.Teleporting = false
                        SetStatus("IDLE")
                        return
                    end
                end

                local Blocked = BlockBeforeLeaving(OtherPlayer)

                --// They left while we waited: nothing to leave for any more.
                --// Not a failed hop, so it does not use up an attempt.
                if OtherPlayer.Parent ~= Players then
                    S.DangerHopAttempts = math.max(S.DangerHopAttempts - 1, 0)
                    S.DangerHopStarted = false
                    S.Teleporting = false
                    SetStatus("IDLE")
                    return
                end

                if not Blocked then
                    Notify("DANGER", "@" .. OtherPlayer.Name .. " is not blocked yet; leaving anyway", 6)
                end

                SetStatus("LEAVING (DANGER GROUP)")

                --// Report before the hop, like every other leave, naming the
                --// player whose group made us leave.
                if AICFeature.ReportBeforeLeave then
                    AICFeature.ReportBeforeLeave(OtherPlayer)
                end

                local Target = FindOtherServer()

                local Success, Error = pcall(function()
                    if Target then
                        TeleportService:TeleportToPlaceInstance(game.PlaceId, Target, Player)
                    else
                        TeleportService:Teleport(game.PlaceId, Player)
                    end
                end)

                if Success then
                    return
                end

                warn("[ServerHop] Danger group hop failed:", Error)
                S.DangerHopStarted = false
                S.Teleporting = false

                if S.DangerHopAttempts < DANGER_HOP_MAX_ATTEMPTS then
                    task.delay(DANGER_HOP_RETRY_DELAY, LeaveFor, OtherPlayer)
                else
                    SetStatus("TELEPORT FAILED")
                    Notify("DANGER", "Teleport failed after " .. DANGER_HOP_MAX_ATTEMPTS .. " attempts", 7)
                end
            end)
        end

        --// IsInGroupAsync where the client has it, IsInGroup otherwise. Errors
        --// from the second reach the caller's pcall.
        local function IsInGroup(OtherPlayer, GroupId)
            local Success, IsMember = pcall(function()
                return OtherPlayer:IsInGroupAsync(GroupId)
            end)

            if Success then
                return IsMember
            end

            return OtherPlayer:IsInGroup(GroupId)
        end

        --// The first of GroupIds the player is in, or nil.
        local function FindDangerGroup(OtherPlayer, GroupIds)
            for _, GroupId in ipairs(GroupIds) do
                if IsInGroup(OtherPlayer, GroupId) then
                    return GroupId
                end
            end

            return nil
        end

        --// Group membership is asked once per player; the answer is kept for
        --// as long as they are in the server.
        local function CheckDangerGroup(OtherPlayer)
            if OtherPlayer == Player or OtherPlayer.Parent ~= Players then
                return
            end

            local UserId = tostring(OtherPlayer.UserId)

            if S.DangerUsers[UserId] then
                LeaveFor(OtherPlayer)
                return
            end

            if S.CheckedUsers[UserId] or S.CheckInFlight[UserId] then
                return
            end

            local GroupIds = GetDangerGroupIds()

            if #GroupIds == 0 then
                return
            end

            S.CheckInFlight[UserId] = true

            local Version = S.GroupListVersion

            task.spawn(function()
                local Success, GroupId = pcall(FindDangerGroup, OtherPlayer, GroupIds)

                --// The group list changed while asking: the scan asks again.
                if Version ~= S.GroupListVersion then
                    return
                end

                if not Success then
                    S.CheckFailures[UserId] = (S.CheckFailures[UserId] or 0) + 1
                    warn("[ServerHop] Group check failed for @" .. OtherPlayer.Name .. ":", GroupId)

                    --// Not marked checked: a scan after the retry delay asks
                    --// again, until the last attempt has failed.
                    if S.CheckFailures[UserId] >= GROUP_CHECK_MAX_ATTEMPTS then
                        S.CheckedUsers[UserId] = true
                        Notify("GROUP CHECK", "Could not check @" .. OtherPlayer.Name .. " after " .. GROUP_CHECK_MAX_ATTEMPTS .. " tries", 7,
                            "GROUP CHECK", GROUP_CHECK_NOTICE_COOLDOWN)
                    else
                        task.wait(GROUP_CHECK_RETRY_DELAY)
                    end

                    S.CheckInFlight[UserId] = nil
                    return
                end

                S.CheckInFlight[UserId] = nil
                S.CheckFailures[UserId] = nil
                S.CheckedUsers[UserId] = true

                if GroupId and OtherPlayer.Parent == Players then
                    S.DangerUsers[UserId] = GroupId
                    S.LogVersion += 1
                    LeaveFor(OtherPlayer)
                end
            end)
        end

        ------------------------------------------------------------------------
        --// Join Alerts
        ------------------------------------------------------------------------

        --// "@a, @b, @c, @d and 2 more"
        local function ListNames(Names)
            local Shown = {}

            for Index = 1, math.min(#Names, JOIN_ALERT_MAX_NAMES) do
                Shown[Index] = Names[Index]
            end

            local Text = table.concat(Shown, ", ")

            if #Names > JOIN_ALERT_MAX_NAMES then
                Text ..= string.format(" and %d more", #Names - JOIN_ALERT_MAX_NAMES)
            end

            return Text
        end

        --// Shows the queued alerts as at most two notices: who joined, and
        --// who was already here. Anyone who left or was whitelisted while
        --// queued, or Join Alerts switched off meanwhile, is dropped.
        local function FlushJoinAlerts()
            S.AlertFlushScheduled = false

            local Queue = S.AlertQueue
            S.AlertQueue = {}

            if not Feature.JoinAlerts.Enabled then
                return
            end

            local Joined, Here = {}, {}

            for _, Entry in ipairs(Queue) do
                if Entry.Player.Parent == Players and not IsWhitelisted(Entry.Player) then
                    table.insert(Entry.WasAlreadyHere and Here or Joined, "@" .. Entry.Player.Name)
                end
            end

            if #Joined == 1 then
                NotifyAction("PLAYER JOINED", Joined[1] .. " joined the server", 6)
            elseif #Joined > 1 then
                NotifyAction("PLAYERS JOINED", string.format("%d players joined: %s", #Joined, ListNames(Joined)), 6)
            end

            if #Here == 1 then
                NotifyAction("PLAYER ALREADY HERE", Here[1] .. " is already in this server", 6)
            elseif #Here > 1 then
                NotifyAction("PLAYERS ALREADY HERE", string.format("%d players off the whitelist are here: %s", #Here, ListNames(Here)), 6)
            end
        end

        --// Force skips the repeat window, for a fresh look at who is here.
        local function AlertIfStranger(OtherPlayer, WasAlreadyHere, Force)
            if OtherPlayer == Player or not Feature.JoinAlerts.Enabled or IsWhitelisted(OtherPlayer) then
                return
            end

            local UserId = tostring(OtherPlayer.UserId)
            local now = os.clock()

            if not Force and now - (S.AlertSeen[UserId] or -math.huge) < JOIN_ALERT_REPEAT_SECONDS then
                return
            end

            S.AlertSeen[UserId] = now
            table.insert(S.AlertQueue, { Player = OtherPlayer, WasAlreadyHere = WasAlreadyHere })

            if not S.AlertFlushScheduled then
                S.AlertFlushScheduled = true
                task.delay(JOIN_ALERT_BATCH_SECONDS, FlushJoinAlerts)
            end
        end

        --// Join Alerts switched on, or loaded on: everyone already here, in
        --// one notice.
        function ServerHop:ScanJoinAlerts()
            for _, OtherPlayer in ipairs(Players:GetPlayers()) do
                AlertIfStranger(OtherPlayer, true, true)
            end
        end

        ------------------------------------------------------------------------

        local function OnPlayerAdded(OtherPlayer, WasAlreadyHere)
            if OtherPlayer == Player then
                return
            end

            local UserId = tostring(OtherPlayer.UserId)

            if not S.Online[UserId] then
                S.Online[UserId] = true
                RecordLog(OtherPlayer, WasAlreadyHere and "present" or "joined")
            end

            task.defer(AlertIfStranger, OtherPlayer, WasAlreadyHere)

            --// Before the first Update the profile, and with it the
            --// whitelist, is not loaded yet; that scan covers everyone.
            if S.Ready then
                CheckDangerGroup(OtherPlayer)
            end
        end

        Context.Connect(Players.PlayerAdded, function(OtherPlayer)
            OnPlayerAdded(OtherPlayer, false)
        end)

        Context.Connect(Players.PlayerRemoving, function(OtherPlayer)
            local UserId = tostring(OtherPlayer.UserId)

            if S.Online[UserId] then
                RecordLog(OtherPlayer, "left")
            end

            --// AlertSeen is kept, so leaving and coming straight back is not
            --// announced twice.
            S.Online[UserId] = nil
            S.CheckedUsers[UserId] = nil
            S.CheckFailures[UserId] = nil
        end)

        for _, OtherPlayer in ipairs(Players:GetPlayers()) do
            OnPlayerAdded(OtherPlayer, true)
        end

        Context.Connect(TeleportService.TeleportInitFailed, function(Who, _, ErrorMessage)
            --// Auto Block and Party System teleport too, and report their own
            --// failures; only a teleport of ours is reported here.
            if Who ~= Player or not (S.Teleporting or S.DangerHopStarted) then
                return
            end

            S.Teleporting = false
            SetStatus("TELEPORT FAILED")
            Notify("SERVER", tostring(ErrorMessage or "Teleport failed"), 6)

            --// A failed danger hop tries again on the next scan.
            S.DangerHopStarted = false
        end)

        function ServerHop:Update()
            local now = os.clock()

            if now - S.LastScan < SCAN_INTERVAL then
                return
            end

            S.LastScan = now

            --// A profile that loaded with Join Alerts on: everyone already here.
            if not S.Ready and Feature.JoinAlerts.Enabled then
                ServerHop:ScanJoinAlerts()
            end

            S.Ready = true

            for _, OtherPlayer in ipairs(Players:GetPlayers()) do
                CheckDangerGroup(OtherPlayer)
            end
        end

        return ServerHop
    end,
}
]======],
	["Features/ServerUI.lua"] = [======[
-- ServerUI owns the Server tab, ported from Iambatman's Server page, status
-- card, server info panel and join log: this server's players, place, Job
-- ID, FPS and ping; Rejoin, Server Hop, Copy Job ID and Join Job ID; the
-- Leave On Danger Group and Join Alerts toggles; the Player Log; and the
-- Server Browser window listing public servers. ServerHop does the work.
return {
    Name = "ServerUI",
    IsFeature = true,
    Dependencies = {"Runtime", "SaveConfig", "Components", "ServerHop", "Floating"},

    Start = function(Context)
        local UI = Context.UI
        local UIRef = Context.UIRef
        local CONFIG = Context.CONFIG
        local AICUI = Context.AICUI
        local AICProfile = Context.AICProfile
        local Services = Context.Services
        local Players = Services.Players
        local Player = Context.Player
        local NotifyAction = Context.NotifyAction
        local ServerHop = Context.ServerHop
        local Floating = Context.Floating

        local New, Label, Button = Floating.New, Floating.Label, Floating.Button
        local ClearChildren = Floating.ClearChildren

        local INFO_INTERVAL = 1
        local LOG_SHOWN = 15
        local WINDOW_WIDTH = 600
        local WINDOW_HEIGHT = 420
        --// Share of the window the server list takes; the details get the rest.
        local LIST_WIDTH_SCALE = 0.5
        local ROW_HEIGHT = 40
        --// FPS and ping colour bands, as in Iambatman.
        local FPS_GOOD, FPS_OK = 50, 30
        local PING_GOOD, PING_OK = 100, 200

        local Module = {
            Name = "ServerUI",
            IsFeature = true,
            S = {
                LastInfo = 0,
                FrameCount = 0,
                FrameTime = 0,
                FPS = nil,
                PlaceName = "Place " .. tostring(game.PlaceId),
                LogLabels = {},
                LogVersion = -1,
                --// Server Browser
                Built = false,
                Servers = {},
                Cursor = nil,
                Loading = false,
                Selected = nil,
            },
        }

        local S = Module.S
        local Window, ListScroll, DetailScroll, StatusLabel, RefreshButton, MoreButton

        task.spawn(function()
            local Success, Info = pcall(function()
                return Services.MarketplaceService:GetProductInfo(game.PlaceId)
            end)

            if Success and type(Info) == "table" and Info.Name then
                S.PlaceName = Info.Name
            end
        end)

        local function ShortJobId(JobId)
            JobId = tostring(JobId or "")

            if #JobId > 18 then
                return JobId:sub(1, 8) .. "..." .. JobId:sub(-6)
            end

            return JobId ~= "" and JobId or "-"
        end

        local function GetPingMs()
            local Success, Seconds = pcall(function()
                return Player:GetNetworkPing()
            end)

            return Success and type(Seconds) == "number" and math.floor(Seconds * 1000 + 0.5) or nil
        end

        local function CopyJobId(JobId)
            if JobId == "" then
                NotifyAction("SERVER", "This server has no Job ID", 3)
            elseif Floating.CopyText(JobId) then
                NotifyAction("SERVER", "Job ID copied")
            else
                NotifyAction("SERVER", "Copy is not available here. Job ID: " .. JobId, 8)
            end
        end

        --// The current server as a server list entry.
        local function CurrentServerEntry()
            return {
                Id = tostring(game.JobId or ""),
                Playing = #Players:GetPlayers(),
                MaxPlayers = Players.MaxPlayers,
                Ping = GetPingMs(),
                FPS = S.FPS,
                IsCurrent = true,
            }
        end

        ------------------------------------------------------------------------
        --// Current Server
        ------------------------------------------------------------------------

        local Section = UIRef.ServerSection

        UIRef.ServerPlayersLabel = Section:AddLabel("PLAYERS  0")
        UIRef.ServerJobLabel = Section:AddLabel("JOB ID  -")
        UIRef.ServerFPSLabel = Section:AddLabel("FPS  --")
        UIRef.ServerPingLabel = Section:AddLabel("PING  -- MS")
        UIRef.ServerStatusLabel = Section:AddLabel("STATUS  IDLE")

        Section:AddButton{
            Name = "Rejoin",
            Callback = function()
                ServerHop:Rejoin()
            end,
        }

        Section:AddButton{
            Name = "Server Hop",
            Callback = function()
                ServerHop:Hop()
            end,
        }

        Section:AddButton{
            Name = "Copy Job ID",
            Callback = function()
                CopyJobId(tostring(game.JobId or ""))
            end,
        }

        UIRef.JoinJobIdBox = Section:AddTextBox{ Name = "Job ID", Default = "", Callback = function() end }

        Section:AddButton{
            Name = "Join Job ID",
            Callback = function()
                ServerHop:Join(UIRef.JoinJobIdBox:Get())
            end,
        }

        Section:AddButton{
            Name = "Open Server Browser",
            Callback = function()
                Module:ToggleBrowser()
            end,
        }

        ------------------------------------------------------------------------
        --// Server Safety
        ------------------------------------------------------------------------

        local SafetySection = UIRef.ServerSafetySection

        AICUI.BindFeatureToggle("DangerGroupHop", "Leave On Danger Group", function()
            ServerHop.S.LastScan = 0
        end, SafetySection)

        SafetySection:AddNote("Leaves if a Danger Group member is here (Danger Whitelist exempt; Block Whitelist too with Whitelist Skips Safety)")
        SafetySection:AddNote("Toggle, groups and whitelist are shared by every profile")

        --// A list of IDs kept in CONFIG[Key] and the global file. Removing
        --// or reordering a row saves too; OnChanged runs after every save.
        --// Returns the list and its save function.
        local function AddGlobalIdList(Title, Key, OnChanged)
            local List = SafetySection:AddPriority(Title, CONFIG[Key] or {})
            CONFIG[Key] = List.Priority

            local function Save()
                CONFIG[Key] = List.Priority
                AICProfile.WriteGlobalStore()

                if OnChanged then
                    OnChanged()
                end
            end

            local OriginalRemove = List.Remove
            local OriginalMoveUp = List.MoveUp
            local OriginalMoveDown = List.MoveDown

            function List:Remove(Entry)
                local Changed = OriginalRemove(self, Entry)
                Save()
                return Changed
            end

            function List:MoveUp(Entry)
                OriginalMoveUp(self, Entry)
                Save()
            end

            function List:MoveDown(Entry)
                OriginalMoveDown(self, Entry)
                Save()
            end

            return List, Save
        end

        --// Groups whose members Leave On Danger Group leaves for.
        local DangerGroups, SaveDangerGroups = AddGlobalIdList("Danger Groups", "DANGER_GROUP_IDS", function()
            ServerHop:ResetGroupChecks()
        end)

        local DangerGroupBox = SafetySection:AddTextBox{ Name = "Group ID", Default = "", Callback = function() end }

        SafetySection:AddButton{
            Name = "Add Group ID",
            Callback = function()
                local Id = tostring(DangerGroupBox:Get() or ""):gsub("%s+", "")

                if not Id:match("^%d+$") then
                    NotifyAction("Danger Groups", "Enter a numeric group ID")
                    return
                end

                if table.find(CONFIG.DANGER_GROUP_IDS or {}, Id) then
                    NotifyAction("Danger Groups", Id .. " is already on the list")
                    return
                end

                DangerGroups:Add(Id)
                SaveDangerGroups()
                DangerGroupBox:Set("")
                NotifyAction("Danger Groups", "Added group " .. Id)
            end,
        }

        --// Players Leave On Danger Group stays for, separate from the Auto
        --// Block whitelist.
        local DangerPlayerOptions = {}
        local DangerPlayerDropdown
        local RefreshDangerPlayerDropdown

        local DangerWhitelist, SaveDangerWhitelist = AddGlobalIdList("Danger Whitelist", "DANGER_WHITELIST", function()
            --// Someone taken off the list is acted on at the next frame.
            ServerHop.S.LastScan = 0
            task.defer(RefreshDangerPlayerDropdown)
        end)

        AICUI.ShowUserNames(DangerWhitelist)

        local function AddDangerWhitelist(UserId, Label)
            if ServerHop:IsDangerWhitelisted(UserId) then
                NotifyAction("Danger Whitelist", tostring(Label) .. " is already on the list")
                return false
            end

            DangerWhitelist:Add(UserId)
            SaveDangerWhitelist()
            NotifyAction("Danger Whitelist", "Added " .. tostring(Label))
            return true
        end

        --// DangerPlayerOptions maps each label to its UserId text.
        function RefreshDangerPlayerDropdown()
            table.clear(DangerPlayerOptions)

            local Options = {}

            for _, OtherPlayer in ipairs(Players:GetPlayers()) do
                if OtherPlayer ~= Player and not ServerHop:IsDangerWhitelisted(OtherPlayer.UserId) then
                    local Text = string.format("%s (@%s)  %d", OtherPlayer.DisplayName, OtherPlayer.Name, OtherPlayer.UserId)
                    DangerPlayerOptions[Text] = tostring(OtherPlayer.UserId)
                    table.insert(Options, Text)
                end
            end

            table.sort(Options, function(A, B)
                return string.lower(A) < string.lower(B)
            end)

            if #Options == 0 then
                Options = {"No other players"}
            end

            --// A new dropdown is appended to the section, so it takes the
            --// old one's slot to keep its place in the list.
            local Order = DangerPlayerDropdown and DangerPlayerDropdown.Row and DangerPlayerDropdown.Row.LayoutOrder

            if DangerPlayerDropdown and DangerPlayerDropdown.Remove then
                DangerPlayerDropdown:Remove()
            end

            DangerPlayerDropdown = SafetySection:AddDropdown{
                Name = "Add Player In Server",
                Options = Options,
                Callback = function(Value)
                    local Id = DangerPlayerOptions[Value]

                    if Id then
                        AddDangerWhitelist(Id, Value)
                    end
                end,
            }

            if Order and DangerPlayerDropdown.Row then
                DangerPlayerDropdown.Row.LayoutOrder = Order
            end
        end

        RefreshDangerPlayerDropdown()

        local DangerWhitelistBox = SafetySection:AddTextBox{ Name = "User ID", Default = "", Callback = function() end }

        SafetySection:AddButton{
            Name = "Add User ID",
            Callback = function()
                local Id = tostring(DangerWhitelistBox:Get() or ""):gsub("%s+", "")

                if not Id:match("^%d+$") then
                    NotifyAction("Danger Whitelist", "Enter a numeric UserId")
                    return
                end

                if AddDangerWhitelist(Id, Id) then
                    DangerWhitelistBox:Set("")
                end
            end,
        }

        SafetySection:AddButton{
            Name = "Clear Danger Whitelist",
            Callback = function()
                DangerWhitelist:SetPriority({})
                SaveDangerWhitelist()
                NotifyAction("Danger Whitelist", "Cleared")
            end,
        }

        Context.Connect(Players.PlayerAdded, function()
            RefreshDangerPlayerDropdown()
        end)

        Context.Connect(Players.PlayerRemoving, function()
            task.defer(RefreshDangerPlayerDropdown)
        end)

        AICUI.BindFeatureToggle("JoinAlerts", "Join Alerts", function(Enabled)
            if Enabled then
                ServerHop:ScanJoinAlerts()
            end
        end, SafetySection)

        SafetySection:AddNote("Notifies about players off the Auto Block whitelist")

        ------------------------------------------------------------------------
        --// Player Log
        ------------------------------------------------------------------------

        local LogSection = UIRef.ServerLogSection

        LogSection:AddButton{
            Name = "Clear Log",
            Callback = function()
                ServerHop:ClearLog()
            end,
        }

        local function DescribeLogEntry(Entry)
            local Tags = ""
            local OtherPlayer = Players:GetPlayerByUserId(tonumber(Entry.UserId) or 0)

            if Context.AICFeature.IsWhitelisted and Context.AICFeature.IsWhitelisted(Entry.UserId) then
                Tags ..= "  [WHITELIST]"
            end

            if ServerHop:IsDangerWhitelisted(Entry.UserId) then
                Tags ..= "  [DANGER WHITELIST]"
            end

            if OtherPlayer and ServerHop:IsDangerPlayer(OtherPlayer) then
                Tags ..= "  [DANGER]"
            end

            return string.format("%s  %s  @%s%s", Entry.Time, string.upper(Entry.Event), Entry.Name, Tags)
        end

        local function RefreshLog()
            if ServerHop.S.LogVersion == S.LogVersion then
                return
            end

            S.LogVersion = ServerHop.S.LogVersion

            local Lines = {}

            for Index, Entry in ipairs(ServerHop:GetLog()) do
                if Index > LOG_SHOWN then
                    break
                end

                Lines[Index] = DescribeLogEntry(Entry)
            end

            if #Lines == 0 then
                Lines[1] = "NO PLAYERS LOGGED YET"
            end

            for Index, Text in ipairs(Lines) do
                local LogLabel = S.LogLabels[Index]

                if not LogLabel then
                    LogLabel = LogSection:AddLabel(Text)
                    S.LogLabels[Index] = LogLabel
                end

                LogLabel:Set(Text)
                LogLabel:SetVisible(true)
            end

            for Index = #Lines + 1, #S.LogLabels do
                S.LogLabels[Index]:SetVisible(false)
            end
        end

        ------------------------------------------------------------------------
        --// Server Browser
        ------------------------------------------------------------------------

        local function PingText(Ping)
            return Ping and string.format("%d ms", math.floor(Ping + 0.5)) or "n/a"
        end

        local function FPSText(FPS)
            return FPS and tostring(math.floor(FPS + 0.5)) or "n/a"
        end

        local function BuildDetail()
            local Theme = UI.Theme
            local Server = S.Selected

            ClearChildren(DetailScroll)

            if not Server then
                Label(DetailScroll, "Pick a server from the list", 12, { TextColor3 = Theme.TextMuted, LayoutOrder = 1 })
                return
            end

            local IsCurrent = Server.Id == tostring(game.JobId or "")

            if IsCurrent then
                Server = CurrentServerEntry()
            end

            Label(DetailScroll, (IsCurrent and "◇  THIS SERVER" or "◇  PUBLIC SERVER"), 13, {
                TextColor3 = Theme.Cyan,
                Font = Floating.Fonts.Bold,
                LayoutOrder = 1,
            })
            Label(DetailScroll, string.format("PLAYERS  %d / %d", Server.Playing or 0, Server.MaxPlayers or 0), 10, {
                Font = Floating.Fonts.Bold,
                LayoutOrder = 2,
            })
            Label(DetailScroll, string.format("PING  %s  ·  FPS  %s", PingText(Server.Ping), FPSText(Server.FPS)):upper(), 10, {
                TextColor3 = Theme.TextSecondary,
                LayoutOrder = 3,
            })
            Label(DetailScroll, "JOB ID  " .. Server.Id, 9, {
                TextColor3 = Theme.TextMuted,
                TextWrapped = true,
                TextTruncate = Enum.TextTruncate.None,
                AutomaticSize = Enum.AutomaticSize.Y,
                LayoutOrder = 4,
            })

            local Copy = Button(DetailScroll, "COPY JOB ID", Theme.Text, { LayoutOrder = 5 })
            UI:_Connect(Copy.Activated, function()
                CopyJobId(Server.Id)
            end)

            if not IsCurrent then
                local Join = Button(DetailScroll, "JOIN", Theme.Cyan, { LayoutOrder = 6 })
                UI:_Connect(Join.Activated, function()
                    ServerHop:Join(Server.Id)
                end)

                Label(DetailScroll, "Roblox's server list gives player counts only, not names, for other servers", 9, {
                    TextColor3 = Theme.TextMuted,
                    TextWrapped = true,
                    TextTruncate = Enum.TextTruncate.None,
                    AutomaticSize = Enum.AutomaticSize.Y,
                    LayoutOrder = 7,
                })
                return
            end

            Label(DetailScroll, "PLAYERS IN THIS SERVER", 8, {
                TextColor3 = Theme.TextMuted,
                Font = Floating.Fonts.Bold,
                LayoutOrder = 6,
            })

            local Here = Players:GetPlayers()

            table.sort(Here, function(A, B)
                if A == Player or B == Player then
                    return A == Player and B ~= Player
                end

                return string.lower(A.Name) < string.lower(B.Name)
            end)

            for Index, OtherPlayer in ipairs(Here) do
                local Display = OtherPlayer.DisplayName ~= "" and OtherPlayer.DisplayName or OtherPlayer.Name
                local Text = string.format("%s%s  @%s", OtherPlayer == Player and "YOU  ·  " or "", Display, OtherPlayer.Name)

                if ServerHop:IsDangerPlayer(OtherPlayer) then
                    Text ..= "  [DANGER]"
                end

                Label(DetailScroll, Text, 10, {
                    TextColor3 = OtherPlayer == Player and Theme.Cyan
                        or (ServerHop:IsDangerPlayer(OtherPlayer) and Theme.Danger or Theme.Text),
                    LayoutOrder = 6 + Index,
                })
            end
        end

        local function SelectServer(Server)
            S.Selected = Server
            S.DetailSignature = nil
            BuildDetail()
        end

        local function AddServerRow(Server, Order)
            local Theme = UI.Theme
            local IsCurrent = Server.IsCurrent == true

            local Row = New("TextButton", {
                Parent = ListScroll,
                Size = UDim2.new(1, -6, 0, ROW_HEIGHT),
                BackgroundColor3 = IsCurrent and Theme.PanelHover or Theme.Element,
                BackgroundTransparency = 0.1,
                BorderSizePixel = 0,
                Text = "",
                AutoButtonColor = false,
                LayoutOrder = Order,
            })

            Floating.Hover(Row)

            --// Accent bar on the left: cyan for the server we are in.
            New("Frame", {
                Parent = Row,
                BackgroundColor3 = IsCurrent and Theme.Cyan or Theme.BorderDim,
                BorderSizePixel = 0,
                Position = UDim2.fromOffset(0, 6),
                Size = UDim2.new(0, 2, 1, -12),
            })

            Label(Row, string.format("%s%d / %d PLAYERS", IsCurrent and "◆  YOU ARE HERE  ·  " or "◇  ", Server.Playing or 0, Server.MaxPlayers or 0), 10, {
                Position = UDim2.fromOffset(10, 5),
                Size = UDim2.new(1, -18, 0, 15),
                TextColor3 = IsCurrent and Theme.Cyan or Theme.Text,
                Font = Floating.Fonts.Bold,
            })
            Label(Row, string.format("PING %s  ·  FPS %s  ·  %s", PingText(Server.Ping), FPSText(Server.FPS), ShortJobId(Server.Id)):upper(), 8, {
                Position = UDim2.fromOffset(10, 22),
                Size = UDim2.new(1, -18, 0, 12),
                TextColor3 = Theme.TextMuted,
            })

            UI:_Connect(Row.Activated, function()
                SelectServer(Server)
            end)
        end

        local function RedrawList()
            ClearChildren(ListScroll)

            for Index, Server in ipairs(S.Servers) do
                AddServerRow(Server, Index)
            end
        end

        --// Reset starts over with this server on top; otherwise the next page.
        local function LoadServers(Reset)
            if S.Loading or (not Reset and not S.Cursor) then
                return
            end

            if Reset then
                S.Cursor = nil
                S.Servers = { CurrentServerEntry() }
                RedrawList()
            end

            S.Loading = true
            StatusLabel.Text = Reset and "Loading public servers..." or "Loading more servers..."

            task.spawn(function()
                local Servers, NextCursor, Error = ServerHop:ReadPublicServers(not Reset and S.Cursor or nil)
                S.Loading = false

                if not Servers then
                    S.Cursor = nil
                    MoreButton.Visible = false
                    StatusLabel.Text = "Could not load servers: " .. tostring(Error)
                    return
                end

                local Seen = {}

                for _, Server in ipairs(S.Servers) do
                    Seen[Server.Id] = true
                end

                for _, Server in ipairs(Servers) do
                    if not Seen[Server.Id] then
                        Seen[Server.Id] = true
                        table.insert(S.Servers, Server)
                        AddServerRow(Server, #S.Servers)
                    end
                end

                S.Cursor = NextCursor
                MoreButton.Visible = NextCursor ~= nil
                StatusLabel.Text = string.format("%d servers%s", #S.Servers, NextCursor and "  ·  more available" or "")
            end)
        end

        local function BuildBrowser()
            local Theme = UI.Theme

            Window = Floating.CreateWindow({
                Title = "SERVER BROWSER",
                Subtitle = "Public servers  //  pick one to see it and join",
                Width = WINDOW_WIDTH,
                Height = WINDOW_HEIGHT,
            })

            RefreshButton = Button(Window.Body, "◇  REFRESH", Theme.Cyan, { Size = UDim2.fromOffset(100, 26) })
            MoreButton = Button(Window.Body, "LOAD MORE", Theme.Text, {
                Position = UDim2.fromOffset(106, 0),
                Size = UDim2.fromOffset(90, 26),
                Visible = false,
            })
            StatusLabel = Label(Window.Body, "", 9, {
                Position = UDim2.fromOffset(206, 0),
                Size = UDim2.new(1, -206, 0, 26),
                TextColor3 = Theme.TextMuted,
            })

            local Lists = New("Frame", {
                Parent = Window.Body,
                BackgroundTransparency = 1,
                Position = UDim2.fromOffset(0, 34),
                Size = UDim2.new(1, 0, 1, -34),
            })

            ListScroll = Floating.Scroller(Lists, UDim2.new(), UDim2.new(LIST_WIDTH_SCALE, -4, 1, 0), 4, 4)
            DetailScroll = Floating.Scroller(Lists, UDim2.new(LIST_WIDTH_SCALE, 4, 0, 0), UDim2.new(1 - LIST_WIDTH_SCALE, -4, 1, 0), 8, 6)

            UI:_Connect(RefreshButton.Activated, function()
                LoadServers(true)
            end)

            UI:_Connect(MoreButton.Activated, function()
                LoadServers(false)
            end)

            S.Built = true
        end

        function Module:ToggleBrowser()
            if not Floating.Available() then
                return
            end

            if not S.Built then
                BuildBrowser()
            end

            if Window.IsOpen then
                Window:Close()
                return
            end

            Window:Open()
            SelectServer(CurrentServerEntry())
            LoadServers(true)
        end

        ------------------------------------------------------------------------

        local function ColorBand(Value, Good, Ok, LowerIsBetter)
            local Theme = UI.Theme

            if not Value then
                return Theme.TextMuted
            end

            local IsGood = LowerIsBetter and Value < Good or not LowerIsBetter and Value >= Good
            local IsOk = LowerIsBetter and Value < Ok or not LowerIsBetter and Value >= Ok
            return IsGood and Theme.Cyan or (IsOk and Theme.Warning or Theme.Danger)
        end

        local function RefreshInfo()
            local Ping = GetPingMs()

            UIRef.ServerPlayersLabel:Set(string.format("PLAYERS  %d / %d  //  %s", #Players:GetPlayers(), Players.MaxPlayers, S.PlaceName))
            UIRef.ServerJobLabel:Set(string.format("JOB ID  %s  //  PLACE  %d", ShortJobId(game.JobId), game.PlaceId))
            UIRef.ServerFPSLabel:Set("FPS  " .. (S.FPS and tostring(S.FPS) or "--"))
            UIRef.ServerFPSLabel:SetColor(ColorBand(S.FPS, FPS_GOOD, FPS_OK, false))
            UIRef.ServerPingLabel:Set("PING  " .. (Ping and tostring(Ping) or "--") .. " MS")
            UIRef.ServerPingLabel:SetColor(ColorBand(Ping, PING_GOOD, PING_OK, true))
            UIRef.ServerStatusLabel:Set("STATUS  " .. ServerHop:GetStatus())

            RefreshLog()

            --// The current server's details follow its players while shown,
            --// redrawn only when they change so the scroll stays put.
            if Window and Window.IsOpen and S.Selected and S.Selected.Id == tostring(game.JobId or "") then
                local Names = {}

                for _, OtherPlayer in ipairs(Players:GetPlayers()) do
                    table.insert(Names, OtherPlayer.Name .. (ServerHop:IsDangerPlayer(OtherPlayer) and "!" or ""))
                end

                table.sort(Names)

                local Signature = table.concat(Names, ",")

                if Signature ~= S.DetailSignature then
                    S.DetailSignature = Signature
                    BuildDetail()
                end
            end
        end

        --// Heartbeat drives this every frame, so it also counts the FPS.
        function Module:Update(dt)
            S.FrameCount += 1
            S.FrameTime += dt or 0

            if S.FrameTime >= INFO_INTERVAL then
                S.FPS = math.floor(S.FrameCount / S.FrameTime + 0.5)
                S.FrameCount = 0
                S.FrameTime = 0
            end

            local now = os.clock()

            if now - S.LastInfo >= INFO_INTERVAL then
                S.LastInfo = now
                RefreshInfo()
            end
        end

        return Module
    end,
}
]======],
}
